void solve(int r, int n, vector<bool>& col, vector<bool>& d1,
           vector<bool>& d2, int& count) {
    if (r == n) { ++count; return; }
    for (int c = 0; c < n; ++c) {
        if (col[c] || d1[r - c + n - 1] || d2[r + c]) continue;
        col[c] = d1[r - c + n - 1] = d2[r + c] = true;
        solve(r + 1, n, col, d1, d2, count);
        col[c] = d1[r - c + n - 1] = false;
    }
}

