bool canPartitionKSubsets(vector<int> nums, int k) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (k <= 0 || sum % k) return false;
    int target = sum / k;
    sort(nums.rbegin(), nums.rend());          // big items first
    if (nums[0] > target) return false;
    vector<int> bucket(k, 0);
    function<bool(int)> place = [&](int i) {
        if (i == (int)nums.size()) return true;  // all placed, sums equal
        for (int j = 0; j < k; ++j) {
            if (bucket[j] + nums[i] > target) continue;
            bucket[j] += nums[i];
            if (place(i + 1)) return true;
            bucket[j] -= nums[i];
            if (bucket[j] == 0) break;           // empty buckets are symmetric
        }
        return false;
    };
    return place(0);
}

