void perm(vector<int>& a, int s, int& cnt) {
    if (s == (int)a.size()) { ++cnt; return; }
    for (int i = s; i < (int)a.size(); ++i) {
        if (i > s && a[i] == a[i - 1]) continue;
        swap(a[s], a[i]);
        perm(a, s + 1, cnt);
        swap(a[s], a[i]);
    }
}
int main() {
    vector<int> a = {0, 0, 1, 9};
    int cnt = 0;
    perm(a, 0, cnt);
    cout << cnt;
}
